// emp host entry: lazy pages, nested chain, expression context chunks, and a
// literal remote entry URL for the hand-written static micro-frontend.
const REMOTE_ENTRY = '/remote/remoteEntry.js';
const VIEWS = ['/views/v1.html', '/views/v2.html'];

(window as any).__MFE_REMOTE__ = REMOTE_ENTRY;
(window as any).__MFE_VIEWS__ = VIEWS;

import(/* webpackIgnore: true */ REMOTE_ENTRY).catch(() => undefined);

const loadPage = (name: string) => {
  if (name === 'a') return import('./pages/page-a');
  if (name === 'b') return import('./pages/page-b');
  if (name === 'nest') return import('./pages/page-nest');
  return import('./pages/page-a');
};
loadPage('a').catch(() => undefined);
loadPage('b').catch(() => undefined);
loadPage('nest').catch(() => undefined);

// expression import -> webpack context chunks
const loadWidget = (name: string) =>
  import('./widgets/' + name).then((m: any) => m.widget && m.widget());
loadWidget('w1').catch(() => undefined);
loadWidget('w2').catch(() => undefined);